package main

import (
	"bufio"
	"fmt"
	"os"
)


func main() {
   scanner := bufio.NewScanner(os.Stdin)
   scanner.Scan()
   frase := scanner.Text()


   vogais := make([]rune, 0)
   consoantes := make([]rune, 0)

    for _, letra := range frase {
        switch letra {
        case 'a', 'e', 'i', 'o', 'u':
            vogais = append(vogais, letra)
        case ' ' :

        default:
            consoantes = append(consoantes, letra)
        }

    }
    fmt.Println(string(vogais))
    fmt.Println(string(consoantes))
}
